  'designFiles.documentTemplate.capabilityImages': 'Incolla immagini o trascina file immagine sull\'editor; le immagini caricate vengono inserite nella posizione del cursore.',
  'designFiles.documentTemplate.scenarioHeading': 'Guida agli scenari',
  'designFiles.documentTemplate.scenario.prototype': 'Per i prototipi, descrivi obiettivo del prodotto, utenti target, flussi, schermate, moduli, stati di interazione, breakpoint responsive e design token come colore, tipografia, spaziatura, raggio e movimento.',
  'designFiles.documentTemplate.scenario.wireframe': 'Per i wireframe, descrivi il flusso utente, l\'elenco delle schermate, la gerarchia del layout, i blocchi di contenuto, i vincoli di bassa fedeltà e le domande a cui la struttura deve rispondere prima del design visivo.',
  'designFiles.documentTemplate.scenario.mobile': 'Per le app mobile, elenca piattaforme di destinazione, schermate, modello di navigazione, gesti, pattern nativi, dimensioni dei dispositivi, stati e design token mobile.',
  'designFiles.documentTemplate.scenario.slideDeck': 'Per le slide, scrivi una scaletta PPT paginata: una sezione per slide con titolo, scopo, messaggio chiave, prove, direzione visiva, note del relatore ed esigenze di esportazione.',
  'designFiles.documentTemplate.scenario.document': 'Per i documenti, definisci pubblico, tono, struttura delle sezioni, materiale di partenza, citazioni o dati, aspettative di layout e requisiti PDF/esportazione.',
  'designFiles.documentTemplate.scenario.image': 'Per le immagini, specifica soggetto, proporzioni, composizione, stile visivo, token di brand, file di riferimento e vincoli negativi.',
  'designFiles.documentTemplate.scenario.video': 'Per i video, prepara uno storyboard con scene, tempi, sottotitoli, movimento, risorse, note audio e formato di output.',
  'designFiles.documentTemplate.scenario.hyperframes': 'Per HyperFrames, descrivi il pezzo di motion in HTML: scene, timeline, sottotitoli, momenti reattivi all\'audio, transizioni e requisiti di acquisizione/esportazione.',
  'designFiles.documentTemplate.scenario.audio': 'Per l\'audio, definisci direzione di voce o musica, durata, atmosfera, copione o testo, ritmo, note di pronuncia e uso finale.',
  'designFiles.documentTemplate.scenario.liveArtifact': 'Per gli artefatti live, descrivi fonti dati, frequenza di aggiornamento, widget, filtri, interazioni, stati vuoto/caricamento/errore ed eventuali avvisi o automazioni.',
  'designFiles.documentTemplate.scenario.designSystem': 'Per i design system, elenca obiettivi del brand, token, tipografia, colore, spaziatura, componenti, risorse, riferimenti e regole da seguire o evitare.',
  'designFiles.documentTemplate.scenario.default': 'Descrivi pubblico, risultato da consegnare, contenuti necessari, riferimenti, vincoli e come dovrebbe apparire il lavoro finito.',
  'designFiles.documentTemplate.nextHeading': 'Passo successivo',
  'designFiles.documentTemplate.nextBody': 'Rivedi e modifica questo documento, poi chiedi a OpenDesign di generare, rivedere o operare a partire da esso.',

