  'nextStep.planImproveBody': 'Rifinisci il documento di piano attuale prima di generare l\'artefatto finale.',
  'nextStep.planGeneratePrompt': 'Usa `{file}` come fonte di verità. Leggi prima il documento, mantieni le sue decisioni, poi genera l\'artefatto di design finale che gli corrisponde. Se è una scaletta di slide, genera la presentazione; se è un piano PRD/prototipo, genera il prototipo o i wireframe; se è uno storyboard/brief creativo, genera l\'artefatto visivo/media corrispondente. Prima di generare, segnala eventuali TODO bloccanti o contraddizioni che non riesci a risolvere.',
  'nextStep.planImprovePrompt': 'Leggi `{file}` e miglioralo sul posto come documento di piano modificabile. Restringi l\'ambito, completa le sezioni deboli, aggiungi i controlli di accettazione mancanti e lascia TODO/domande aperte dove serve ancora l\'input dell\'utente. Non generare ancora l\'artefatto di design finale.',
  'nextStep.planImproveArtifactTitle': 'Migliora l\'artefatto',
  'nextStep.planImproveArtifactBody': 'Continua a iterare sull\'artefatto generato invece di tornare alla pianificazione.',
  'nextStep.planImproveArtifactPrompt': 'Migliora `{artifact}` sul posto. Mantieni l\'artefatto funzionante esistente e apporta i miglioramenti di maggiore impatto a prodotto, aspetto visivo, interazione e contenuti. Conserva il comportamento che già funziona, poi riassumi i file modificati e gli eventuali rischi residui.',
  'nextStep.planMergeTitle': 'Allinea documento e artefatto',
  'nextStep.planMergeBody': 'Riconcilia il piano e l\'artefatto generato in modo che avanzino insieme.',
  'nextStep.planMergePrompt': 'Leggi insieme `{document}` e `{artifact}`. Considera il documento come l\'intento e l\'artefatto come l\'implementazione attuale. Riconciliali: aggiorna l\'artefatto in base alle decisioni confermate, aggiorna il documento solo dove è obsoleto e mantieni TODO/domande aperte esplicite per tutto ciò che resta irrisolto. Conserva il comportamento già funzionante e riassumi cosa è cambiato in entrambi i file.',

  'nextStep.projectContinueTitle': 'Continua a lavorare',
